<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PsychologistController extends Controller{
 private function access(Request $r){$u=$r->user();abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('psychologist')||$u->canDo('psychology.view'),403);}
 public function index(Request $r){$this->access($r);$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();$cases=DB::table('psych_cases as c')->join('students as s','s.id','=','c.student_id')->select('c.*','s.last_name','s.first_name','s.middle_name')->orderByDesc('c.opened_on')->limit(50)->get();$plans=DB::table('psych_work_plans')->where('psychologist_user_id',$r->user()->id)->orderBy('starts_on')->limit(20)->get();$stats=['open'=>DB::table('psych_cases')->where('status','open')->count(),'sessions'=>DB::table('psych_sessions')->whereDate('held_at','>=',now()->startOfMonth())->count(),'assessments'=>DB::table('psych_assessments')->whereMonth('assessed_on',now()->month)->whereYear('assessed_on',now()->year)->count(),'consents'=>DB::table('psych_consents')->where('status','active')->count()];return view('psychologist.index',compact('students','cases','plans','stats'));}
 public function caseStore(Request $r){$this->access($r);$d=$r->validate(['student_id'=>'required|exists:students,id','opened_on'=>'required|date','source'=>'nullable|string|max:80','reason'=>'required|string|max:500','priority'=>'required|in:low,normal,high,urgent','goal'=>'nullable|string|max:5000']);DB::table('psych_cases')->insert($d+['status'=>'open','psychologist_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Случай сопровождения открыт');}
 public function caseShow(Request $r,$id){$this->access($r);$case=DB::table('psych_cases as c')->join('students as s','s.id','=','c.student_id')->where('c.id',$id)->select('c.*','s.last_name','s.first_name','s.middle_name','s.current_group_id')->first();abort_unless($case,404);$sessions=DB::table('psych_sessions')->where('psych_case_id',$id)->orderByDesc('held_at')->get();$assessments=DB::table('psych_assessments as a')->leftJoin('psych_methods as m','m.id','=','a.psych_method_id')->where('a.student_id',$case->student_id)->select('a.*','m.name as method_name')->orderByDesc('a.assessed_on')->get();$consents=DB::table('psych_consents')->where('student_id',$case->student_id)->orderByDesc('id')->get();$methods=DB::table('psych_methods')->where('active',1)->orderBy('name')->get();return view('psychologist.case',compact('case','sessions','assessments','consents','methods'));}
 public function caseUpdate(Request $r,$id){$this->access($r);$d=$r->validate(['reason'=>'required|string|max:500','priority'=>'required|in:low,normal,high,urgent','goal'=>'nullable|string|max:5000','status'=>'required|in:open,observation,closed','result'=>'nullable|string|max:5000']);$d['closed_on']=$d['status']==='closed'?now()->toDateString():null;DB::table('psych_cases')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Карточка сопровождения обновлена');}
 public function caseDelete(Request $r,$id){$this->access($r);DB::transaction(function()use($id){DB::table('psych_sessions')->where('psych_case_id',$id)->delete();DB::table('psych_cases')->where('id',$id)->delete();});return redirect()->route('psychologist.index')->with('success','Карточка удалена');}
 public function sessionStore(Request $r,$id){$this->access($r);$d=$r->validate(['held_at'=>'required|date','work_type'=>'required|string|max:100','duration_minutes'=>'nullable|integer|min:1|max:600','format'=>'required|in:individual,group,remote','summary'=>'nullable|string|max:10000','recommendations'=>'nullable|string|max:10000']);DB::table('psych_sessions')->insert($d+['psych_case_id'=>$id,'psychologist_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Приём записан');}
 public function sessionDelete(Request $r,$id){$this->access($r);DB::table('psych_sessions')->where('id',$id)->delete();return back()->with('success','Запись удалена');}
 public function consentStore(Request $r,$student){$this->access($r);$d=$r->validate(['consent_type'=>'required|string|max:120','signed_on'=>'nullable|date','valid_until'=>'nullable|date','signed_by'=>'nullable|string|max:255','note'=>'nullable|string|max:3000']);DB::table('psych_consents')->insert($d+['student_id'=>$student,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Согласие зарегистрировано');}
 public function consentDelete(Request $r,$id){$this->access($r);DB::table('psych_consents')->where('id',$id)->delete();return back()->with('success','Согласие удалено');}
 public function methodStore(Request $r){$this->access($r);$d=$r->validate(['name'=>'required|string|max:255','author'=>'nullable|string|max:255','age_range'=>'nullable|string|max:80','purpose'=>'nullable|string|max:5000','instructions'=>'nullable|string|max:10000']);DB::table('psych_methods')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Методика добавлена');}
 public function methodDelete(Request $r,$id){$this->access($r);DB::table('psych_methods')->where('id',$id)->update(['active'=>0,'updated_at'=>now()]);return back()->with('success','Методика архивирована');}
 public function assessmentStore(Request $r,$student){$this->access($r);$d=$r->validate(['psych_method_id'=>'nullable|exists:psych_methods,id','assessed_on'=>'required|date','status'=>'required|in:planned,completed','result'=>'nullable|string|max:10000','conclusion'=>'nullable|string|max:10000','recommendations'=>'nullable|string|max:10000']);DB::table('psych_assessments')->insert($d+['student_id'=>$student,'psychologist_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Диагностика сохранена');}
 public function assessmentDelete(Request $r,$id){$this->access($r);DB::table('psych_assessments')->where('id',$id)->delete();return back()->with('success','Диагностика удалена');}
 public function planStore(Request $r){$this->access($r);$d=$r->validate(['starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on','title'=>'required|string|max:255','work_type'=>'nullable|string|max:100','content'=>'nullable|string|max:10000','status'=>'required|in:planned,in_progress,completed']);DB::table('psych_work_plans')->insert($d+['psychologist_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','План добавлен');}
 public function planDelete(Request $r,$id){$this->access($r);DB::table('psych_work_plans')->where('id',$id)->where('psychologist_user_id',$r->user()->id)->delete();return back()->with('success','План удалён');}
 public function screenings(Request $r){$this->access($r);$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$methods=DB::table('psych_methods')->where('active',1)->orderBy('name')->get();$rows=DB::table('psych_screenings as x')->leftJoin('study_groups as g','g.id','=','x.study_group_id')->leftJoin('psych_methods as m','m.id','=','x.psych_method_id')->select('x.*','g.name as group_name','m.name as method_name')->orderByDesc('x.id')->get();return view('psychologist.screenings',compact('groups','methods','rows'));}
 public function screeningStore(Request $r){$this->access($r);$d=$r->validate(['title'=>'required|string|max:255','psych_method_id'=>'nullable|exists:psych_methods,id','study_group_id'=>'required|exists:study_groups,id','starts_on'=>'required|date','ends_on'=>'nullable|date|after_or_equal:starts_on','purpose'=>'nullable|string|max:5000']);$id=DB::table('psych_screenings')->insertGetId($d+['status'=>'planned','psychologist_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$students=DB::table('students')->where('current_group_id',$d['study_group_id'])->where('status','active')->pluck('id');foreach($students as $sid)DB::table('psych_screening_assignments')->insertOrIgnore(['psych_screening_id'=>$id,'student_id'=>$sid,'status'=>'assigned','created_at'=>now(),'updated_at'=>now()]);return redirect()->route('psychologist.screenings.show',$id)->with('success','Обследование создано и назначено группе');}
 public function screeningShow(Request $r,$id){$this->access($r);$x=DB::table('psych_screenings as x')->leftJoin('study_groups as g','g.id','=','x.study_group_id')->leftJoin('psych_methods as m','m.id','=','x.psych_method_id')->where('x.id',$id)->select('x.*','g.name as group_name','m.name as method_name')->first();abort_unless($x,404);$rows=DB::table('psych_screening_assignments as a')->join('students as s','s.id','=','a.student_id')->where('a.psych_screening_id',$id)->select('a.*','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->get();$ids=$rows->pluck('student_id');$consented=DB::table('psych_consents')->whereIn('student_id',$ids)->where('status','active')->where(function($q){$q->whereNull('valid_until')->orWhere('valid_until','>=',now()->toDateString());})->distinct()->count('student_id');$done=$rows->where('status','completed');$analytics=['total'=>$rows->count(),'consented'=>$consented,'completed'=>$done->count(),'coverage'=>$rows->count()?round($done->count()*100/$rows->count(),1):0,'avg'=>$done->whereNotNull('score')->avg('score'),'levels'=>$done->groupBy(fn($z)=>$z->level?:'Не указан')->map->count()];return view('psychologist.screening',compact('x','rows','analytics'));}
 public function screeningResult(Request $r,$id,$assignment){$this->access($r);$d=$r->validate(['status'=>'required|in:assigned,in_progress,completed,declined','score'=>'nullable|numeric','level'=>'nullable|string|max:80','result'=>'nullable|string|max:10000']);$d['completed_at']=$d['status']==='completed'?now():null;DB::table('psych_screening_assignments')->where('psych_screening_id',$id)->where('id',$assignment)->update($d+['updated_at'=>now()]);return back()->with('success','Результат сохранён');}
 public function screeningDelete(Request $r,$id){$this->access($r);DB::transaction(function()use($id){DB::table('psych_screening_assignments')->where('psych_screening_id',$id)->delete();DB::table('psych_screenings')->where('id',$id)->delete();});return redirect()->route('psychologist.screenings')->with('success','Обследование удалено');}
 public function reports(Request $r){$this->access($r);$from=$r->input('from',now()->startOfMonth()->toDateString());$to=$r->input('to',now()->toDateString());$sessions=DB::table('psych_sessions')->whereBetween(DB::raw('DATE(held_at)'),[$from,$to])->select('work_type','format',DB::raw('COUNT(*) cnt'),DB::raw('COALESCE(SUM(duration_minutes),0) minutes'))->groupBy('work_type','format')->orderByDesc('cnt')->get();$screenings=DB::table('psych_screenings')->whereBetween('starts_on',[$from,$to])->count();$assessments=DB::table('psych_assessments')->whereBetween('assessed_on',[$from,$to])->count();$casesOpened=DB::table('psych_cases')->whereBetween('opened_on',[$from,$to])->count();$casesClosed=DB::table('psych_cases')->whereBetween('closed_on',[$from,$to])->count();return view('psychologist.reports',compact('from','to','sessions','screenings','assessments','casesOpened','casesClosed'));}

}